<?php

namespace Database\Seeders;

use App\Models\Company;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

class MassiveBackfillSeeder extends Seeder
{
    public function run(): void
    {
        $companies = $this->getCompanies();
        $created = 0;
        $updated = 0;

        foreach ($companies as $data) {
            $slug = $data['slug'] ?? Str::slug($data['name']);
            $company = Company::updateOrCreate(
                ['slug' => $slug],
                array_merge($data, ['slug' => $slug])
            );
            if ($company->wasRecentlyCreated) {
                $created++;
            } else {
                $updated++;
            }
        }

        $this->command->info("MassiveBackfill - Created: {$created}, Updated: {$updated}, Total companies: " . Company::count());
    }

    private function getCompanies(): array
    {
        return array_merge(
            $this->aiMlCompanies(),
            $this->developerToolsCompanies(),
            $this->fintechCompanies(),
            $this->enterpriseSaasCompanies(),
            $this->securityCompanies(),
            $this->healthBioCompanies(),
            $this->climateEnergyCompanies(),
            $this->consumerSocialCompanies(),
            $this->logisticsCommerceCompanies(),
            $this->gamingCompanies(),
            $this->spaceDefenseCompanies(),
            $this->educationCompanies(),
            $this->unicornBackfill(),
        );
    }

